import{b as d,O as r,g as e,j as a}from"./chunks/framework.DcaUmd3X.js";const b=JSON.parse('{"title":"测试用例","description":"","frontmatter":{},"headers":[],"relativePath":"testing/appendix/test-case/index.md","filePath":"测试理论与实践/7.附录：模板与核心概念/02.测试用例.md","lastUpdated":1781538561000}'),o={name:"testing/appendix/test-case/index.md"};function n(l,t,h,s,u,i){return r(),e("div",null,[...t[0]||(t[0]=[a(`<h1 id="测试用例" tabindex="-1">测试用例 <a class="header-anchor" href="#测试用例" aria-label="Permalink to &quot;测试用例&quot;">​</a></h1><blockquote><p>测试用例是测试人员最重要的&quot;施工图纸&quot;。写得清楚，谁跑都能得到一致的结果；写得含糊，三个人跑出三个结论。</p></blockquote><h2 id="测试用例是什么" tabindex="-1">测试用例是什么 <a class="header-anchor" href="#测试用例是什么" aria-label="Permalink to &quot;测试用例是什么&quot;">​</a></h2><p>测试用例是一组为验证特定功能而设计的<strong>输入、执行条件和预期结果</strong>。它是测试执行的最小单位，也是测试活动可追溯、可复现的基础。</p><h2 id="核心要素" tabindex="-1">核心要素 <a class="header-anchor" href="#核心要素" aria-label="Permalink to &quot;核心要素&quot;">​</a></h2><p>先看全景，一条完整的测试用例包含 10 个核心要素：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>要素</th><th>回答的问题</th><th>一句话说明</th><th>填写示例</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>用例编号</strong></td><td>这是哪个用例？</td><td>唯一标识，方便追溯和引用</td><td>TC-LOGIN-001</td></tr><tr><td style="text-align:center;">2</td><td><strong>测试模块</strong></td><td>测的是哪个模块？</td><td>归属的功能模块或需求</td><td>用户登录</td></tr><tr><td style="text-align:center;">3</td><td><strong>用例标题</strong></td><td>测什么？</td><td>一句话说清测试点</td><td>正确账号密码登录成功</td></tr><tr><td style="text-align:center;">4</td><td><strong>前置条件</strong></td><td>测之前要准备什么？</td><td>测试数据、账号、环境状态</td><td>1. 已注册 <a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a> / Abc@123<br>2. 浏览器打开登录页</td></tr><tr><td style="text-align:center;">5</td><td><strong>测试步骤</strong></td><td>怎么做？</td><td>一步步操作描述，别人照做能复现</td><td>1. 输入邮箱 <a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a><br>2. 输入密码 Abc@123<br>3. 点击&quot;登录&quot;按钮</td></tr><tr><td style="text-align:center;">6</td><td><strong>预期结果</strong></td><td>做完应该看到什么？</td><td>每一步对应的预期表现</td><td>1. 输入框显示输入内容<br>2. 密码以掩码显示<br>3. 跳转首页，右上角显示昵称</td></tr><tr><td style="text-align:center;">7</td><td><strong>实际结果</strong></td><td>实际发生了什么？</td><td>执行后填写，与预期对比</td><td>（执行后填写）</td></tr><tr><td style="text-align:center;">8</td><td><strong>优先级</strong></td><td>有多重要？</td><td>时间紧时先跑哪个</td><td>P0</td></tr><tr><td style="text-align:center;">9</td><td><strong>用例状态</strong></td><td>过了还是没过？</td><td>通过 / 失败 / 阻塞 / 跳过</td><td>☐ 通过 ☐ 失败 ☐ 阻塞 ☐ 跳过</td></tr><tr><td style="text-align:center;">10</td><td><strong>备注</strong></td><td>有什么要补充的？</td><td>关联 Bug ID、依赖说明、特殊说明</td><td>无</td></tr></tbody></table><blockquote><p>10 个要素中，<strong>测试步骤</strong>和<strong>预期结果</strong>是最核心的两块——步骤是&quot;怎么做&quot;，预期是&quot;应该看到什么&quot;，两者一一对应。<strong>优先级</strong>则决定了执行顺序——时间不够时，先跑 P0，确保核心流程不出问题。</p></blockquote><hr><h2 id="各要素详解" tabindex="-1">各要素详解 <a class="header-anchor" href="#各要素详解" aria-label="Permalink to &quot;各要素详解&quot;">​</a></h2><h3 id="_1-用例编号" tabindex="-1">1. 用例编号 <a class="header-anchor" href="#_1-用例编号" aria-label="Permalink to &quot;1. 用例编号&quot;">​</a></h3><p>唯一标识，推荐格式：<code>TC-模块缩写-序号</code>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例：TC-LOGIN-001  /  TC-ORDER-015  /  TC-SEARCH-042</span></span>
<span class="line"><span></span></span>
<span class="line"><span>规则：</span></span>
<span class="line"><span>- TC = Test Case 前缀</span></span>
<span class="line"><span>- 模块缩写统一大写，控制在 10 个字符以内</span></span>
<span class="line"><span>- 序号三位数，方便排序</span></span></code></pre></div><blockquote><p>编号一旦确定不要改——别的文档（测试计划、Bug 报告）可能会引用它。</p></blockquote><h3 id="_2-测试模块" tabindex="-1">2. 测试模块 <a class="header-anchor" href="#_2-测试模块" aria-label="Permalink to &quot;2. 测试模块&quot;">​</a></h3><p>说明这个用例属于哪个功能模块。粒度适中即可，不要太粗（&quot;全部功能&quot;），也不要太细（&quot;登录页邮箱输入框&quot;）。</p><table tabindex="0"><thead><tr><th>太粗</th><th>合适</th><th>太细</th></tr></thead><tbody><tr><td>用户功能</td><td>用户登录</td><td>登录页-邮箱输入框-格式校验</td></tr></tbody></table><h3 id="_3-用例标题" tabindex="-1">3. 用例标题 <a class="header-anchor" href="#_3-用例标题" aria-label="Permalink to &quot;3. 用例标题&quot;">​</a></h3><p><strong>一句话说清测什么</strong>。最重要的写作原则：让没看过需求文档的人也能看懂。</p><table tabindex="0"><thead><tr><th>坏标题</th><th>好标题</th><th>为什么</th></tr></thead><tbody><tr><td>&quot;登录测试&quot;</td><td>正确账号密码登录成功</td><td>没说测什么场景</td></tr><tr><td>&quot;测试搜索&quot;</td><td>输入关键词搜索，验证结果包含关键词</td><td>太笼统</td></tr><tr><td>&quot;边界测试&quot;</td><td>购物车数量输入 0 件，验证提示&quot;至少选择 1 件&quot;</td><td>没说具体边界值</td></tr></tbody></table><blockquote><p>好标题公式：<strong>条件 + 操作 + 预期</strong>。&quot;正确账号密码（条件）→ 点击登录（操作）→ 登录成功跳转首页（预期）&quot;</p></blockquote><h3 id="_4-前置条件" tabindex="-1">4. 前置条件 <a class="header-anchor" href="#_4-前置条件" aria-label="Permalink to &quot;4. 前置条件&quot;">​</a></h3><p>测之前必须准备好的东西。漏了前置条件，换了个人跑用例就跑不通。</p><p><strong>前置条件检查清单：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>示例</th></tr></thead><tbody><tr><td>测试数据</td><td>&quot;已存在账号 <a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a>，余额 100 元&quot;</td></tr><tr><td>环境状态</td><td>&quot;购物车中已添加 3 件商品&quot;</td></tr><tr><td>账号权限</td><td>&quot;以管理员角色登录&quot;</td></tr><tr><td>配置开关</td><td>&quot;已开启双因素认证&quot;</td></tr><tr><td>关联数据</td><td>&quot;有 5 条待处理订单&quot;</td></tr></tbody></table><h3 id="_5-测试步骤-预期结果" tabindex="-1">5. 测试步骤 + 预期结果 <a class="header-anchor" href="#_5-测试步骤-预期结果" aria-label="Permalink to &quot;5. 测试步骤 + 预期结果&quot;">​</a></h3><p>步骤和预期要<strong>一一对应</strong>，每做一步都明确写出&quot;做完这一步应该看到什么&quot;。不要挤在一段话里。</p><table tabindex="0"><thead><tr><th>写法</th><th>步骤</th><th>预期结果</th></tr></thead><tbody><tr><td>❌ 挤在一起</td><td>打开页面输入账号密码点登录</td><td>登录成功</td></tr><tr><td>✅ 一一对应</td><td>1. 打开登录页</td><td>1. 显示登录表单</td></tr><tr><td></td><td>2. 输入邮箱 <a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a></td><td>2. 输入框显示输入内容</td></tr><tr><td></td><td>3. 输入密码 Abc@123</td><td>3. 密码以掩码显示</td></tr><tr><td></td><td>4. 点击&quot;登录&quot;</td><td>4. 跳转至首页，右上角显示昵称</td></tr></tbody></table><blockquote><p>每一步的预期结果都应该是<strong>可观察、可验证</strong>的。如果某一步的预期是&quot;系统正常&quot;——这句话等于没说。</p></blockquote><h3 id="_6-用例状态" tabindex="-1">6. 用例状态 <a class="header-anchor" href="#_6-用例状态" aria-label="Permalink to &quot;6. 用例状态&quot;">​</a></h3><p>执行后必须标记状态，不是&quot;跑完了&quot;就完了：</p><table tabindex="0"><thead><tr><th>状态</th><th>含义</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>通过</strong></td><td>实际结果与预期一致</td><td>一切正常</td></tr><tr><td><strong>失败</strong></td><td>实际结果与预期不一致</td><td>有 Bug，需要关联 Bug ID</td></tr><tr><td><strong>阻塞</strong></td><td>无法执行</td><td>环境挂了、前置条件不满足、依赖 Bug 未修复</td></tr><tr><td><strong>跳过</strong></td><td>本轮决定不执行</td><td>需求变更、该功能本版不测</td></tr></tbody></table><h3 id="_7-优先级" tabindex="-1">7. 优先级 <a class="header-anchor" href="#_7-优先级" aria-label="Permalink to &quot;7. 优先级&quot;">​</a></h3><p>决定用例的执行顺序——时间不够时，按优先级从高到低跑，确保核心流程不受影响。</p><table tabindex="0"><thead><tr><th>级别</th><th>含义</th><th>什么时候用</th></tr></thead><tbody><tr><td><strong>P0</strong></td><td>最高优先级</td><td>核心业务流程（登录、下单、支付），每次必跑</td></tr><tr><td><strong>P1</strong></td><td>高优先级</td><td>重要功能、高频使用场景，回归测试必跑</td></tr><tr><td><strong>P2</strong></td><td>中优先级</td><td>一般功能、分支流程，完整回归时跑</td></tr><tr><td><strong>P3</strong></td><td>低优先级</td><td>边缘场景、极少触发的路径，时间充裕才跑</td></tr></tbody></table><blockquote><p>优先级和 Bug 严重性不一样——Bug 严重性是&quot;出了 Bug 影响多大&quot;，用例优先级是&quot;这个用例有多重要&quot;。一个 P0 用例失败了意味着核心流程有问题，必须修了才能上线。</p></blockquote><h3 id="_8-备注" tabindex="-1">8. 备注 <a class="header-anchor" href="#_8-备注" aria-label="Permalink to &quot;8. 备注&quot;">​</a></h3><p>补充任何有助于理解或用例执行的信息，不是必填，但以下情况建议填写：</p><table tabindex="0"><thead><tr><th>场景</th><th>备注内容示例</th></tr></thead><tbody><tr><td>用例因 Bug 失败</td><td>&quot;Bug ID: BUG-20240615-003，开发预计下轮修复&quot;</td></tr><tr><td>用例依赖其他用例</td><td>&quot;依赖 TC-ORDER-001 创建的订单数据&quot;</td></tr><tr><td>特殊环境要求</td><td>&quot;仅在 Chrome 125+ 生效，Safari 不支持&quot;</td></tr><tr><td>已知限制</td><td>&quot;数据量 &gt; 10000 条时性能会下降，已在 P2 Bug 跟踪&quot;</td></tr><tr><td>跳过原因</td><td>&quot;本版本未实现该功能，延期至 V3.0&quot;</td></tr></tbody></table><blockquote><p>备注的价值在<strong>回头看</strong>的时候体现——三个月后别人翻到这个用例，一看备注就知道当时为什么失败、为什么跳过。</p></blockquote><hr><h2 id="写好用例的四条铁律" tabindex="-1">写好用例的四条铁律 <a class="header-anchor" href="#写好用例的四条铁律" aria-label="Permalink to &quot;写好用例的四条铁律&quot;">​</a></h2><h3 id="_1-一个用例只测一个点" tabindex="-1">1. 一个用例只测一个点 <a class="header-anchor" href="#_1-一个用例只测一个点" aria-label="Permalink to &quot;1. 一个用例只测一个点&quot;">​</a></h3><table tabindex="0"><thead><tr><th>❌ 一个用例塞太多</th><th>✅ 拆成两个</th></tr></thead><tbody><tr><td>标题：登录功能测试</td><td>TC-LOGIN-001：正确账号密码登录成功</td></tr><tr><td>步骤 1-4：正常登录</td><td>TC-LOGIN-002：错误密码登录失败</td></tr><tr><td>步骤 5-8：错误密码登录</td><td>TC-LOGIN-003：空账号点击登录提示必填</td></tr><tr><td>步骤 9-12：空账号登录</td><td>TC-LOGIN-004：连续 5 次错误锁定账号</td></tr></tbody></table><p>拆开后每条用例独立执行、独立标记状态，Bug 关联也精准。</p><h3 id="_2-步骤要能复现" tabindex="-1">2. 步骤要能复现 <a class="header-anchor" href="#_2-步骤要能复现" aria-label="Permalink to &quot;2. 步骤要能复现&quot;">​</a></h3><p>写用例时假设执行者<strong>完全不熟悉这个功能</strong>。不要写&quot;正常完成下单流程&quot;——什么是&quot;正常&quot;？选了什么商品？用的什么支付方式？</p><h3 id="_3-预期结果要可量化" tabindex="-1">3. 预期结果要可量化 <a class="header-anchor" href="#_3-预期结果要可量化" aria-label="Permalink to &quot;3. 预期结果要可量化&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模糊预期</th><th>量化预期</th></tr></thead><tbody><tr><td>&quot;页面加载正常&quot;</td><td>&quot;3 秒内显示商品列表，首条商品图片可见&quot;</td></tr><tr><td>&quot;提示错误&quot;</td><td>&quot;红色弹窗提示&#39;密码错误，剩余 3 次尝试机会&#39;&quot;</td></tr><tr><td>&quot;跳转成功&quot;</td><td>&quot;URL 变为 /home，页面标题显示&#39;首页&#39;&quot;</td></tr></tbody></table><h3 id="_4-数据要具体-不要用-某个" tabindex="-1">4. 数据要具体，不要用&quot;某个&quot; <a class="header-anchor" href="#_4-数据要具体-不要用-某个" aria-label="Permalink to &quot;4. 数据要具体，不要用&quot;某个&quot;&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模糊数据</th><th>具体数据</th></tr></thead><tbody><tr><td>&quot;某个已注册账号&quot;</td><td>&quot;<a href="mailto:test@example.com" target="_blank" rel="noreferrer">test@example.com</a> / Abc@123&quot;</td></tr><tr><td>&quot;一件商品&quot;</td><td>&quot;SKU=SH-001，商品名=蓝牙耳机，价格=299，库存=50&quot;</td></tr><tr><td>&quot;输入一大段文字&quot;</td><td>&quot;输入 500 字的用户评论（附具体文本）&quot;</td></tr></tbody></table><hr><h2 id="用例评审检查单" tabindex="-1">用例评审检查单 <a class="header-anchor" href="#用例评审检查单" aria-label="Permalink to &quot;用例评审检查单&quot;">​</a></h2><p>用例写完后，拉上开发和产品一起过一遍。拿着这个清单逐条对：</p><table tabindex="0"><thead><tr><th style="text-align:center;">#</th><th>检查点</th><th>通过标准</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>完整性</strong></td><td>正向、异常、边界都覆盖了吗？</td></tr><tr><td style="text-align:center;">2</td><td><strong>可复现性</strong></td><td>换个人不看需求文档，能照着跑通吗？</td></tr><tr><td style="text-align:center;">3</td><td><strong>数据具体性</strong></td><td>所有测试数据都写死了吗？（没有&quot;某个&quot;&quot;随便&quot;）</td></tr><tr><td style="text-align:center;">4</td><td><strong>步骤预期对应</strong></td><td>每一步都有明确的预期结果吗？</td></tr><tr><td style="text-align:center;">5</td><td><strong>无冗余</strong></td><td>有没有两条用例实际上测的是同一个东西？</td></tr><tr><td style="text-align:center;">6</td><td><strong>可追溯</strong></td><td>每条用例能关联到需求或功能点吗？</td></tr></tbody></table><hr><h2 id="常见坑点" tabindex="-1">常见坑点 <a class="header-anchor" href="#常见坑点" aria-label="Permalink to &quot;常见坑点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>坑</th><th>后果</th><th>正确做法</th></tr></thead><tbody><tr><td>步骤和预期不一一对应</td><td>不知道哪一步出了问题</td><td>每步写一条预期</td></tr><tr><td>前置条件缺失</td><td>换人跑不通，浪费时间排查环境</td><td>数据、账号、状态全部明确</td></tr><tr><td>预期结果模糊</td><td>&quot;通过&quot;还是&quot;失败&quot;全靠执行人主观判断</td><td>预期量化到能拍照片对比</td></tr><tr><td>一条用例测多个点</td><td>部分失败时整条用例标记失败，统计失真</td><td>一个点一条用例</td></tr><tr><td>用例标题太笼统</td><td>看标题不知道测什么，只能点进去看步骤</td><td>标题包含条件 + 操作 + 预期</td></tr></tbody></table><hr><h2 id="本章小结" tabindex="-1">本章小结 <a class="header-anchor" href="#本章小结" aria-label="Permalink to &quot;本章小结&quot;">​</a></h2><ol><li>测试用例 10 要素：编号、模块、标题、前置条件、步骤、预期结果、实际结果、优先级、状态、备注</li><li>步骤和预期结果<strong>一一对应</strong>是最重要的写作原则</li><li>四条铁律：一个点一条用例、步骤能复现、预期能量化、数据要具体</li><li>写完后拿评审检查单过一遍——完整性、可复现性、数据具体性、对应关系、无冗余、可追溯</li></ol>`,61)])])}const g=d(o,[["render",n]]);export{b as __pageData,g as default};
